// Password Analyzer
const data = $('1. HTML Parser').first().json.extracted_data;
const passwords = data.passwords || [];

const KEYBOARD_PATTERNS = ['qwerty', 'asdfgh', 'zxcvbn', '123456', '654321'];
const COMMON_WORDS = ['password', 'admin', 'login', 'welcome', 'master'];

function analyzePassword(pwd) {
  const patterns = [];
  let score = 100;

  // Length check
  if (pwd.length < 8) {
    score -= 30;
    patterns.push('troppo_corta');
  } else if (pwd.length < 12) {
    score -= 10;
  }

  // Complexity
  const hasUpper = /[A-Z]/.test(pwd);
  const hasLower = /[a-z]/.test(pwd);
  const hasDigit = /\d/.test(pwd);
  const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(pwd);

  const complexity = [hasUpper, hasLower, hasDigit, hasSpecial].filter(Boolean).length;
  if (complexity < 2) {
    score -= 25;
    patterns.push('bassa_complessità');
  }

  // Keyboard patterns
  const pwdLower = pwd.toLowerCase();
  for (const pattern of KEYBOARD_PATTERNS) {
    if (pwdLower.includes(pattern)) {
      score -= 20;
      patterns.push('keyboard_pattern');
      break;
    }
  }

  // Common words
  for (const word of COMMON_WORDS) {
    if (pwdLower.includes(word)) {
      score -= 25;
      patterns.push('parola_comune');
      break;
    }
  }

  // Repeated characters
  if (/(.)\1{2,}/.test(pwd)) {
    score -= 15;
    patterns.push('caratteri_ripetuti');
  }

  return {
    masked: pwd.length > 4 ? pwd.slice(0, 2) + '*'.repeat(pwd.length - 4) + pwd.slice(-2) : '****',
    length: pwd.length,
    complexity: complexity,
    score: Math.max(0, score),
    patterns: patterns,
    level: score >= 80 ? 'ECCELLENTE' : score >= 60 ? 'BUONO' : score >= 40 ? 'MEDIO' : score >= 20 ? 'BASSO' : 'CRITICO'
  };
}

const analyses = passwords.map(pwd => analyzePassword(pwd));
const avgScore = analyses.length > 0 
  ? analyses.reduce((sum, a) => sum + a.score, 0) / analyses.length 
  : 100;

const allPatterns = analyses.flatMap(a => a.patterns);
const recommendations = [];

if (allPatterns.includes('troppo_corta')) recommendations.push('Utilizzare password di almeno 12 caratteri');
if (allPatterns.includes('bassa_complessità')) recommendations.push('Includere maiuscole, numeri e caratteri speciali');
if (allPatterns.includes('keyboard_pattern')) recommendations.push('Evitare sequenze di tastiera prevedibili');
if (allPatterns.includes('parola_comune')) recommendations.push('Non utilizzare parole comuni');

return {
  json: {
    password_analysis: {
      total: passwords.length,
      individual: analyses,
      average_score: Math.round(avgScore),
      overall_level: avgScore >= 80 ? 'ECCELLENTE' : avgScore >= 60 ? 'BUONO' : avgScore >= 40 ? 'MEDIO' : avgScore >= 20 ? 'BASSO' : 'CRITICO',
      common_patterns: [...new Set(allPatterns)],
      recommendations: recommendations
    }
  }
};

// Security Assessor
const data = $('1. HTML Parser').first().json.extracted_data;
const metadata = $('1. HTML Parser').first().json.metadata;
const pwdAnalysis = $('5. Password Analyzer').first().json.password_analysis;

const vulnerabilities = [];
const threats = [];
let score = 100;

// Email exposure
if (data.emails.length > 0) {
  vulnerabilities.push({
    type: 'EMAIL_EXPOSURE',
    severity: 'MEDIA',
    count: data.emails.length,
    description: `${data.emails.length} indirizzi email esposti pubblicamente`
  });
  score -= data.emails.length * 5;
}

// Data breaches
if (data.breaches.length > 0) {
  vulnerabilities.push({
    type: 'DATA_BREACH',
    severity: 'ALTA',
    count: data.breaches.length,
    description: `Presente in ${data.breaches.length} data breach`
  });
  score -= data.breaches.length * 15;
  threats.push('Credential Stuffing Attack');
}

// Password exposure
if (data.passwords.length > 0) {
  vulnerabilities.push({
    type: 'PASSWORD_EXPOSURE',
    severity: 'CRITICA',
    count: data.passwords.length,
    description: `${data.passwords.length} password esposte in chiaro`
  });
  score -= 30;
  threats.push('Account Takeover');
  threats.push('Identity Theft');
}

// Large digital footprint
if (data.social_profiles.length > 5) {
  vulnerabilities.push({
    type: 'LARGE_DIGITAL_FOOTPRINT',
    severity: 'MEDIA',
    count: data.social_profiles.length,
    description: 'Ampia presenza social aumenta superficie di attacco'
  });
  score -= 10;
  threats.push('Social Engineering');
  threats.push('Spear Phishing');
}

// Calculate grade
let grade;
if (score >= 90) grade = 'A';
else if (score >= 80) grade = 'B';
else if (score >= 70) grade = 'C';
else if (score >= 60) grade = 'D';
else grade = 'F';

// Exposure level
let exposureLevel;
if (score <= 20) exposureLevel = 'CRITICO';
else if (score <= 40) exposureLevel = 'ALTO';
else if (score <= 60) exposureLevel = 'MODERATO';
else if (score <= 80) exposureLevel = 'BASSO';
else exposureLevel = 'MINIMO';

const recommendations = [];
if (vulnerabilities.some(v => v.type === 'PASSWORD_EXPOSURE')) {
  recommendations.push('URGENTE: Cambiare immediatamente tutte le password esposte');
  recommendations.push('Attivare autenticazione a due fattori');
}
if (vulnerabilities.some(v => v.type === 'DATA_BREACH')) {
  recommendations.push('Verificare credenziali su tutti gli account compromessi');
}
if (threats.includes('Social Engineering')) {
  recommendations.push('Aumentare consapevolezza su tecniche di social engineering');
}

return {
  json: {
    security_assessment: {
      score: Math.max(0, score),
      grade: grade,
      exposure_level: exposureLevel,
      vulnerabilities: vulnerabilities,
      threats: [...new Set(threats)],
      recommendations: recommendations,
      digital_footprint_score: 100 - Math.max(0, score)
    }
  }
};

