// Aggregatore finale - Combina tutti i risultati
const htmlData = $('1. HTML Parser').first().json;
const perplexityResult = $('2. Perplexity OSINT Verification').first().json;
const openaiCorrelation = $('3. OpenAI Data Correlation').first().json;
const psychProfile = $('4. Anthropic Psychological Profile').first().json;
const pwdAnalysis = $('5. Password Analyzer').first().json;
const securityAssessment = $('6. Security Assessor').first().json;
const narrative = $('7. Anthropic Report Narrative').first().json;

// Parse narrative JSON
let narrativeData = {};
try {
  const jsonMatch = narrative.message.content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    narrativeData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  narrativeData = {
    executive_summary: narrative.message.content.substring(0, 500),
    correlation_narrative: 'Vedere sezione dati per dettagli.',
    conclusions: 'Conclusioni basate sui dati raccolti.'
  };
}

const finalReport = {
  report_metadata: {
    title: 'REPORT INFO INVESTIGATIVO',
    generated_at: new Date().toISOString(),
    generated_by: 'FidelinvestigatorAI - Enhanced AI Edition',
    ai_providers: ['Perplexity', 'OpenAI GPT-4', 'Anthropic Claude'],
    confidence_level: 'ALTA'
  },

  executive_summary: narrativeData.executive_summary || '',

  extracted_data: htmlData.extracted_data,
  extraction_metadata: htmlData.metadata,

  osint_verification: {
    provider: 'Perplexity AI',
    result: perplexityResult.choices?.[0]?.message?.content || 'N/A',
    timestamp: new Date().toISOString()
  },

  correlation_analysis: {
    provider: 'OpenAI GPT-4',
    result: openaiCorrelation.message?.content || 'N/A',
    narrative: narrativeData.correlation_narrative || ''
  },

  psychological_profile: {
    provider: 'Anthropic Claude',
    result: psychProfile.message?.content || 'N/A'
  },

  password_analysis: pwdAnalysis.password_analysis,

  security_assessment: securityAssessment.security_assessment,

  conclusions: narrativeData.conclusions || '',

  risk_summary: {
    security_grade: securityAssessment.security_assessment.grade,
    exposure_level: securityAssessment.security_assessment.exposure_level,
    security_score: securityAssessment.security_assessment.score,
    total_vulnerabilities: securityAssessment.security_assessment.vulnerabilities.length,
    total_threats: securityAssessment.security_assessment.threats.length
  }
};

return { json: finalReport };
